-- 001: local SQLite persistence. Forward-only additive migration; back up before deployment.
CREATE TABLE outlets (id TEXT PRIMARY KEY, owner TEXT, outlet TEXT, status TEXT NOT NULL, month TEXT, version INTEGER, current INTEGER NOT NULL DEFAULT 0, amount_cents INTEGER, data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL);
CREATE INDEX idx_outlets_owner_status ON outlets(owner,status);
CREATE INDEX idx_outlets_outlet_month ON outlets(outlet,month);
CREATE TABLE reports (id TEXT PRIMARY KEY, owner TEXT, outlet TEXT, status TEXT NOT NULL, month TEXT, version INTEGER, current INTEGER NOT NULL DEFAULT 0, amount_cents INTEGER, data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL);
CREATE INDEX idx_reports_owner_status ON reports(owner,status);
CREATE INDEX idx_reports_outlet_month ON reports(outlet,month);
