CREATE INDEX idx_contents_owner_status ON contents(owner,status);
CREATE INDEX idx_contents_outlet_month ON contents(outlet,month);
CREATE TABLE organizations (id TEXT PRIMARY KEY, owner TEXT, outlet TEXT, status TEXT NOT NULL, month TEXT, version INTEGER, current INTEGER NOT NULL DEFAULT 0, amount_cents INTEGER, data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL);
CREATE INDEX idx_organizations_owner_status ON organizations(owner,status);
CREATE INDEX idx_organizations_outlet_month ON organizations(outlet,month);
CREATE UNIQUE INDEX reports_version_unique ON reports(outlet,month,version);
CREATE UNIQUE INDEX reports_current_unique ON reports(outlet,month) WHERE current=1 AND status='approved';
CREATE UNIQUE INDEX bill_period_unique ON bills(outlet,month);
CREATE UNIQUE INDEX receipt_bill_unique ON receipts(json_extract(data,'$.billId'));
CREATE UNIQUE INDEX account_owner_unique ON accounts(owner);
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL CHECK(json_valid(value)));
CREATE TABLE users (actor TEXT PRIMARY KEY, role TEXT NOT NULL, status TEXT NOT NULL, binding_version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, subject TEXT NOT NULL, actor TEXT NOT NULL REFERENCES users(actor), binding_version INTEGER NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX sessions_actor ON sessions(actor);
CREATE TABLE idempotency (subject TEXT NOT NULL, key TEXT NOT NULL, request_hash TEXT NOT NULL, result TEXT NOT NULL CHECK(json_valid(result)), created_at TEXT NOT NULL, PRIMARY KEY(subject,key));
CREATE TABLE files (id TEXT PRIMARY KEY, subject TEXT NOT NULL, owner TEXT, name TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL CHECK(size>0 AND size<=5242880), digest TEXT NOT NULL, bytes BLOB NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX files_owner ON files(owner);

